public static void main(String[] args) {
    if (args.length == 0) {
        System.out.println("Please provide a number N as a command-line argument.");
        return;
    }

    long N;
    try {
        N = Long.parseLong(args[0]);
    } catch (NumberFormatException e) {
        System.out.println("Invalid number format.");
        return;
    }

    List<Long> C = new ArrayList<Long>();
    long maxCubeRoot = (long) Math.cbrt(N);

    for (long i = 1; i <= maxCubeRoot; i++) {
        C.add(i * i * i);
    }

    for (int i = C.size() - 1; i >= 0; i--) {
        String S = Long.toString(C.get(i));
        int L = S.length();
        boolean isPalindrome = true;

        for (int j = 0; j < L / 2; j++) {
            if (S.charAt(j) != S.charAt(L - j - 1)) {
                isPalindrome = false;
                break;
            }
        }

        if (isPalindrome) {
            System.out.println(C.get(i));
            break;
        }
    }
}
